test("waiting scene jobs never expire while a long edit is executing", async () => {
 await writeFile(join(root, "batch/queue.json"), JSON.stringify({runs: []}));
 await createSceneEdits({projectId: "source", jobIds: ["first", "second"], ownerId: "tab"});
 const first = await recoverSceneWorker({ownerId: "tab", workerId: "runner"});
 if (!first) throw Error("Missing worker");
 await updateBatch({id: "first", token: [REDACTED], projectId: "worker-first", event: "run"});
 const path = join(root, "batch/queue.json");
 const stored = JSON.parse(await readFile(path, "utf8"));
 for (const run of stored.runs) run.heartbeat = Date.now() - 600_000;
 await writeFile(path, JSON.stringify(stored));
 const state = await getBatchState();
 expect(state.runs.find(r => r.id === "first")?.jobs[0].status).toBe("interrupted");
 expect(state.runs.find(r => r.id === "second")?.jobs[0].status).toBe("ready");
 await cancelBatch({id: "first"});
 await cancelBatch({id: "second"});
});
EOF
node classic/node_modules/prettier/bin/prettier.cjs --write classic/apps/web/src/batch/server.ts classic/apps/web/src/batch/server.test.ts
